INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 17, 'theory', 'Quiz: CSS Cascade, Inheritance, Units and Variables');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 17, 0, 'A paragraph has the class lead and the ID intro. What text color does it get with the rules p { color: red; }, #intro { color: green; } and .lead { color: blue; }?', '["red: the rule for p is written first", "green: the ID selector is the most specific", "blue: the class is last in the markup", "the color is picked at random"]', 1, 'The declaration with the higher specificity wins: an ID weighs more than a class, and a class more than an element name. Source order only counts when specificity is equal.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 17, 1, 'Why is overusing !important harmful?', '["The only way to override it is the same flag with a more specific selector, and styles turn into an arms race", "It disables inheritance for all descendants", "The browser ignores it in external stylesheets", "It slows down page parsing several times over"]', 0, 'The important flag lifts a declaration above ordinary ones, so the only way to override it is another flag. It is justified in utility classes, while order is better kept with layers and low specificity.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 17, 2, 'Which property is inherited by descendants by default?', '["margin", "border", "background", "color"]', 3, 'Text properties are inherited: color, font, line height, alignment. Padding, borders, background and sizes are not, otherwise a border would be drawn again in every nested card.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 17, 3, 'The parent has a font size of 20px. An element inside sets font-size: 1.5em, and its descendant again sets font-size: 1.5em. What size does the descendant get?', '["30px", "20px", "45px", "24px"]', 2, 'Em is computed from the parent''s font, so the values multiply: 20 × 1.5 = 30, then 30 × 1.5 = 45. Rem gives no such surprises: it is always computed from the root element''s font.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 17, 4, 'The variable --accent was declared on :root, and inside the .card block it is given a different value. What happens?', '["The value changes across the whole page", "Only .card and its descendants see the new value, the rest keep the old one", "The browser raises an error: variables cannot be redefined", "The new value is ignored because the root takes precedence"]', 1, 'Custom properties take part in the cascade and are inherited: a value set in a block applies inside it and in its descendants. This is exactly what themes are built on.');
